dir:

































  &DefaultButton;




function dir$dmttbm(p){
  this.constructor(p);
}
dir$dmttbm.prototype = new DirEvent();
dir$dmttbm.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmttbm.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

dir$dmttbmDisabledMasterField(p, g);

}

function dir$dmttbmDisabledMasterField(p, g){

  if(p.valForm('ma_ttbm').trim() != '')
  {
    p.setDisabled('ma_ttbm', true);
  }
  else
  {
    p.setDisabled('ma_ttbm', false);
  }
}






	.control-label.ma_ttbm, .control-label.ten_ttbm
	{	

		color: #499b98;;
	}







declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã trạng thái nhấc máy đã tồn tại.' else N'Pick-up state code already exists.' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã trạng thái nhấc máy đã tồn tại.' else N'Pick-up state code already exists.' end
